/*	Recompute the at-a-glance summary for one event, from source.
	This is the only place the summary is calculated - the response handler and the
	reminder sweep both call it, so the wording and the completeness rule cannot drift	*/

const cfg = $('Config').first().json;
const eventId = String($('Called With').first().json.eventId || '');
const rows = $input.all().map(i => i.json).filter(r => String(r.event_id) === eventId);

const node = (($('Fetch Event').first().json.data || {}).node) || {};
const required = node.requiredStaff || [];
const staff = ((node.staff || {}).edges || []).map(e => e.node);
const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const completePrefix = String(cfg.COMPLETE_PREFIX);
const isDraft = String(node.lifecycleState || '') === 'draft';

/*	The previous summary is the edge detection marker. It lives on the event,
	so no extra state is needed and a human can see it	*/
let previousSummary = '';

for (const cf of (node.customFieldValues || [])) {
	if (String(cf.definitionKey || '') === String(cfg.SUMMARY_FIELD_KEY)) {
		previousSummary = String(cf.value === null || cf.value === undefined ? '' : cf.value);
	}
}

/*	Without somebody in the coordinator role nothing can be told to anybody: responses
	lose their coordinator recipient, the staffing complete email never fires, and the
	publish link has nowhere to go. It is worth saying on the event itself, because that
	is the only surface a human looks at	*/
const coordinatorIds = staff.filter(s => String((s.staffRole || {}).name || '').trim() === coordRole).map(s => s.id);
const hasCoordinator = coordinatorIds.length > 0;
const noCoordinatorNotice = 'NO ' + coordRole.toUpperCase() + ' ASSIGNED, nobody can be notified';

const accepted = rows.filter(r => String(r.status || '') === 'accepted');
const maybeCount = rows.filter(r => String(r.status || '') === 'maybe').length;
const attentionCount = rows.filter(r => String(r.status || '') === 'assign_failed').length;
const attentionText = attentionCount + (attentionCount === 1 ? ' needs attention' : ' need attention');

const answeredIds = {};
for (const r of rows) { answeredIds[String(r.contact_id)] = String(r.status || ''); }

let outstanding = 0;
for (const s of staff) {
	if (!s.contact) { continue; }
	if (String((s.staffRole || {}).name || '').trim() === coordRole) { continue; }
	const st = answeredIds[String(s.contact.id)];
	if (st !== 'accepted' && st !== 'maybe') { outstanding = outstanding + 1; }
}

/*	Per role: required against confirmed. Self correcting when somebody declines and is replaced	*/
let totalRequired = 0;
let totalConfirmed = 0;
const roleParts = [];

for (const req of required) {
	const roleName = String((req.staffRole || {}).name || '').trim();
	const qty = Number(req.quantity || 0);
	if (qty === 0) { continue; }

	/*	An event can list the coordinator in its required personnel, and that line is worth
		showing. It is read from staffing rather than from accepted responses, because a
		coordinator is set by hand and never answers an invitation, and it is deliberately
		kept out of the totals below: counting it would hold every event permanently one
		short, so staffing would never complete	*/
	if (roleName === coordRole) {
		const held = staff.filter(s => String((s.staffRole || {}).name || '').trim() === coordRole).length;
		roleParts.push(Math.min(held, qty) + ' of ' + qty + ' ' + roleName);
		continue;
	}

	const confirmed = accepted.filter(r => String(r.staff_role || '').trim() === roleName).length;
	totalRequired = totalRequired + qty;
	totalConfirmed = totalConfirmed + Math.min(confirmed, qty);
	roleParts.push(confirmed + ' of ' + qty + ' ' + roleName);
}

const complete = totalRequired > 0 && totalConfirmed >= totalRequired;
const stillNeeded = Math.max(totalRequired - totalConfirmed, 0);

/*	Somebody who accepted but could not be assigned only needs a human while there is
	still a place for them. Once the event is fully staffed the slot has been filled by
	somebody else, and once it leaves draft the staffing decision has been made, so in
	both cases the flag is noise. The row itself is kept either way	*/
const showAttention = attentionCount > 0 && !complete && isDraft;

const tail = [];
if (outstanding > 0) { tail.push(outstanding + ' awaiting reply'); }
if (maybeCount > 0) { tail.push(maybeCount + ' undecided'); }
if (showAttention) { tail.push(attentionText); }

let summary;

if (totalRequired === 0) {
	summary = accepted.length + ' confirmed'
		+ (tail.length ? ', ' + tail.join(', ') : '')
		+ ' - no required personnel set on this event';
} else if (complete) {
	summary = completePrefix + ' - ' + roleParts.join(', ');
} else {
	summary = roleParts.join(', ') + ' confirmed - ' + stillNeeded + ' still needed'
		+ (tail.length ? ', ' + tail.join(', ') : '');
}

/*	Appended rather than prefixed, because the complete prefix is the edge detection
	marker and must stay at the front	*/
if (!hasCoordinator) {
	summary = summary + ' - ' + noCoordinatorNotice;
}

/*	The completion email needs two things at once: staffing complete, and somebody to
	send it to. Those can arrive in either order, and a coordinator added after the last
	acceptance is a normal way round.
	So the marker is not was it complete, it is was anybody actually told. An event that
	reached complete with no coordinator carries the warning in its summary, and that
	warning is what says the email has not gone yet. Without this, completing first and
	adding the coordinator second missed the email permanently, because the field already
	read complete and the transition looked spent	*/
const wasNotified = previousSummary.indexOf(completePrefix) === 0
	&& previousSummary.indexOf(noCoordinatorNotice) === -1;

const justCompleted = complete && !wasNotified && isDraft && hasCoordinator;

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

/*	Everybody running this event, as staff records. The ids address the completion email,
	the names go in its body. Read after the caller has finished writing, so somebody who
	has only just been assigned is included	*/
const instructors = staff.filter(s => s.contact && String((s.staffRole || {}).name || '').trim() !== coordRole);
const instructorIds = instructors.map(s => s.id);
const instructorNames = instructors.map(s => esc(s.contact.firstName + ' ' + s.contact.lastName));

return [{ json: {
	eventId: eventId,
	eventTitle: String(node.title || ''),
	summary: summary,
	previousSummary: previousSummary,
	changed: summary !== previousSummary,
	complete: complete,
	justCompleted: justCompleted,
	hasCoordinator: hasCoordinator,
	wasNotified: wasNotified,
	coordinatorIds: coordinatorIds,
	instructorIds: instructorIds,
	roleParts: roleParts,
	instructorNames: instructorNames,
	totalRequired: totalRequired,
	totalConfirmed: totalConfirmed,
	stillNeeded: stillNeeded,
	outstanding: outstanding,
	needsAttention: attentionCount,
	showsAttention: showAttention
} }];

/*	Staffing has just become complete. Two independent gates decide what happens next:
	whether the event publishes on its own, and whether the coordinator is told.
	Both are off by default, so leaving them alone gives an email and no auto publish	*/

const cfg = $('Config').first().json;

/*	A random, unguessable token. 32 bytes from a secure source, hex encoded. It is
	never derived from the event or contact ID. Uses the crypto module where the Code
	node allows it, otherwise the Web Crypto API	*/
const randomToken = () => {
	let bytes = null;
	try {
		bytes = Array.from(require('crypto').randomBytes(32));
	} catch (error) {
		if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
			bytes = Array.from(crypto.getRandomValues(new Uint8Array(32)));
		}
	}
	if (!bytes) {
		throw new Error('No secure random source available. Allow the crypto module in Code nodes (NODE_FUNCTION_ALLOW_BUILTIN=crypto).');
	}
	return bytes.map((b) => b.toString(16).padStart(2, '0')).join('');
};

/*	The summary just calculated, and the event as read at the start of this run. The
	custom fields read here are the same Publish Automatically and Suppress Completion
	Email fields whichever workflow called this one	*/
const s = $('Build Summary').first().json;
const node = (($('Fetch Event').first().json.data || {}).node) || {};

const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const trueValues = String(cfg.CHECKBOX_TRUE_VALUES).split(',').map(v => v.trim().toLowerCase());

/*	The verb for what an instructor does with an event. Both forms appear here: needed to
	deliver this event, and the Delivering it label. Change VERB_BASE and VERB_GERUND in Config	*/
const verb = String(cfg.VERB_BASE || 'deliver').trim();
const verbing = String(cfg.VERB_GERUND || 'delivering').trim();
const titleCase = (v) => v.charAt(0).toUpperCase() + v.slice(1);

const reads = (key) => {
	for (const cf of (node.customFieldValues || [])) {
		if (String(cf.definitionKey || '') !== String(key)) { continue; }
		return trueValues.indexOf(String(cf.value === null || cf.value === undefined ? '' : cf.value).trim().toLowerCase()) !== -1;
	}
	return false;
};

const autoPublish = reads(cfg.AUTO_PUBLISH_FIELD_KEY);
const suppressEmail = reads(cfg.SUPPRESS_EMAIL_FIELD_KEY);

/*	The publish page warns a human about missing personnel and lets them proceed anyway,
	because they may have a reason. An automation has no such reason, so this only fires
	when the requirement is genuinely met	*/
const requirementMet = s.complete === true;
const shouldPublish = autoPublish && requirementMet && String(node.lifecycleState || '') === 'draft';

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

/*	Frame, button and palette come from Config, the same three values the response
	handler uses. Change the look there, not here	*/
const pal = {};
for (const part of String(cfg.EMAIL_PALETTE || '').split('|')) {
	const at = part.indexOf('=');
	if (at > 0) { pal[part.slice(0, at).trim()] = part.slice(at + 1).trim(); }
}

const fill = (tpl, extra) => {
	let s2 = String(tpl || '');
	for (const k of Object.keys(pal)) { s2 = s2.split('%%' + k + '%%').join(pal[k]); }
	for (const k of Object.keys(extra || {})) { s2 = s2.split('%%' + k + '%%').join(extra[k]); }
	return s2;
};

const emailShell = (inner) => fill(cfg.EMAIL_SHELL, { BRAND: esc(cfg.BRAND_NAME), BODY: inner });

/*	Merge fields, not values - Administrate resolves them per recipient, so several
	coordinators each get their own link from a single send. They cannot appear in an
	n8n expression, which is why this string is built here. Left unescaped, because the
	braces must reach Administrate intact	*/
/*	One random publish token per completion email, saved by Save Publish Link before the
	email goes. A newer completion email replaces it, so older publish links expire	*/
const publishToken = randomToken();
const linkTail = '?e=' + '{' + '{ staff.event.encoded_id }' + '}' + '&c=' + '{' + '{ staff.contact.encoded_id }' + '}' + '&t=' + publishToken;
const link = String(cfg.PUBLISH_PAGE_URL) + linkTail;

const button = fill(cfg.EMAIL_BUTTON, { URL: link, LABEL: 'Review and publish this event' });

const running = (s.instructorNames || []).length
	? '<p style="margin:0 0 4px;color:' + pal.MUTED + ';font-size:13px;">' + esc(titleCase(verbing)) + ' it</p>'
		+ '<p style="margin:0 0 18px;">' + s.instructorNames.join(', ') + '</p>'
	: '';

const head = '<p style="margin:0 0 6px;color:' + pal.MUTED + ';font-size:13px;">Staffing complete</p>'
	+ '<p style="margin:0 0 18px;font-size:20px;font-weight:600;color:' + pal.INK + ';">' + esc(s.eventTitle) + '</p>'
	+ '<div style="background:' + pal.TINT + ';border-left:3px solid ' + pal.ACCENT + ';padding:12px 14px;margin:0 0 18px;">'
	+ '<p style="margin:0;">Everybody needed to ' + esc(verb) + ' this event has confirmed. ' + esc((s.roleParts || []).join(', ')) + '.</p></div>'
	+ running;

/*	The email says what happened, not what could happen - otherwise a coordinator gets
	a Publish button for an event that is already live	*/
const body = emailShell(shouldPublish
	? head + '<p style="margin:0 0 16px;">The event is now live in Administrate. Nothing further is needed.</p>'
	: head + '<p style="margin:0 0 4px;">The event is still a draft.</p>' + button
		+ '<p style="margin:0 0 16px;color:' + pal.MUTED + ';">Publishing is your decision. Nothing has been changed.</p>');

/*	Kept for if the people running the event are ever told at this point too. They are
	not at present: their confirmation comes from the publish handler	*/
const instructorBody = emailShell(shouldPublish
	? head + '<p style="margin:0 0 16px;">The event is now live in Administrate. Nothing further is needed from you.</p>'
	: head + '<p style="margin:0 0 16px;">The ' + esc(coordRole) + ' will confirm the event shortly. Nothing further is needed from you.</p>');

const publishBody = shouldPublish
	? JSON.stringify({
		query: 'mutation AutoPublish($eventId: ID!, $state: EventLifecycleState!){ event { update(eventId:$eventId, input:{ lifecycleState:$state }){ event{ id lifecycleState } errors{ label message value } } } }',
		variables: { eventId: s.eventId, state: cfg.PUBLISHED_STATE }
	})
	: JSON.stringify({ query: 'query NoOp { __typename }' });

return [{ json: {
	eventId: s.eventId,
	eventTitle: s.eventTitle,
	coordinatorIds: s.coordinatorIds,
	instructorIds: s.instructorIds || [],
	autoPublish: autoPublish,
	requirementMet: requirementMet,
	published: shouldPublish,
	notify: !suppressEmail && (s.coordinatorIds || []).length > 0,
	notifyInstructors: false,
	publishBody: publishBody,
	publishToken: publishToken,
	now: new Date().toISOString(),
	subject: (shouldPublish ? 'Now live: ' : 'Staffing complete - ') + s.eventTitle,
	body: body,
	instructorBody: instructorBody,
	logMessage: 'Staffing complete for ' + s.eventTitle + '. '
		+ (shouldPublish ? 'Event published automatically.' : (autoPublish ? 'Auto publish is on but the required personnel are not met, so nothing was published.' : coordRole + ' invited to publish.'))
		+ (suppressEmail ? ' Coordinator email suppressed on this event.' : '')
} }];
